function assetUnitCost(assets){const rules=tradeRules(),players=(assets||[]).filter(a=>a.type==='player').length,picks=(assets||[]).filter(a=>a.type==='pick').length,playerUnits=players?Math.ceil(players/Math.max(1,Number(rules.playersPerTradeUnit)||3)):0,pickUnits=picks?Math.ceil(picks/Math.max(1,Number(rules.picksPerTradeUnit)||3)):0;return{players,picks,units:Math.max(playerUnits,pickUnits,(players||picks)?1:0)}}
function freeTradeDesignationEnabled(){return tradeRules().freeTradeDesignationEnabled!==false}
function freeTradeAssetCheck(){return{eligible:false,reason:'Free Trade status is assigned by an authorized reviewer.'}}
function freeTradePackageCheck(){return{eligible:false,reason:'Free Trade status is assigned by an authorized reviewer.',teams:[]}}
function legacyFreeTradeCheck(t){return{eligible:Boolean(t?.freeTrade),reason:t?.freeTrade?'Designated as a Free Trade.':'Standard Trade.'}}
function multiFreeTradeCheck(t){return{eligible:Boolean(t?.freeTrade),reason:t?.freeTrade?'Designated as a Free Trade.':'Standard Trade.'}}
function builderFreeTradeCheck(){return{eligible:false,reason:'Free Trade status can be assigned during committee review.',teams:[]}}
function tradeFreeStatus(t){return{eligible:Boolean(t?.freeTrade),reason:t?.freeTrade?'Designated as a Free Trade.':'Standard Trade.'}}
function tradeLimitReviewRows(t,type='two'){
 const rules=tradeRules();
 const teamIds=type==='multi'?(t.teamIds||[]): [t.teamAId,t.teamBId];
 return teamIds.map(teamId=>{const used=committedTradeUnits(teamId,{excludeId:t.id}),needed=t.freeTrade?0:(type==='multi'?assetUnitCost((t.transfers||[]).filter(x=>x.fromTeamId===teamId).map(x=>x.asset)).units:assetUnitCost(teamId===t.teamAId?(ver(t)?.assetsA||[]):(ver(t)?.assetsB||[])).units),remaining=rules.limitEnabled?Math.max(0,Number(rules.seasonTradeLimit)-used):Infinity;return{teamId,team:teamById(teamId),used,needed,remaining,allowed:!rules.limitEnabled||t.freeTrade||needed<=remaining}})
}
function tradeLimitReviewPanel(t,type='two'){
 const rows=tradeLimitReviewRows(t,type),blocked=rows.filter(r=>!r.allowed);
 const status=t.freeTrade?'FREE TRADE · 0 TRADES CHARGED':'STANDARD TRADE';
 return `<section class="committee-trade-limit-card ${blocked.length&&!t.freeTrade?'has-warning':''}"><div class="committee-trade-limit-card__head"><strong>${status}</strong><span>${freeTradeDesignationEnabled()?'Authorized reviewers may change this designation.':'Free Trade designations are disabled.'}</span></div><div class="committee-trade-limit-grid">${rows.map(r=>`<div><span>${escapeHtml(r.team?.fullName||r.teamId)}</span><strong>${Number.isFinite(r.remaining)?`${r.remaining} remaining`:'Unlimited'}</strong><small>${t.freeTrade?'0 used by this trade':`${r.needed} required`}</small></div>`).join('')}</div>${blocked.length&&!t.freeTrade?`<div class="committee-trade-limit-warning"><strong>${escapeHtml(blocked.map(r=>r.team?.fullName||r.teamId).join(', '))} ${blocked.length===1?'is':'are'} out of trades.</strong><span>If Trade is Free, please toggle ON.</span></div>`:''}</section>`
}
function canToggleFreeTrade(t,type='two',a=me()){
 if(!freeTradeDesignationEnabled()||!canVoteOnTrades(a))return false;
 if(type==='multi')return !multiCommitteeConflict(t,a);
 return !committeeConflict(t,a);
}
function freeTradeToggleMarkup(t,type='two'){
 const a=me(),allowed=canToggleFreeTrade(t,type,a);
 if(!allowed)return t.freeTrade?'<span class="pill pill--success">FREE TRADE · 0 Trades Charged</span>':'';
 return `<label class="free-trade-designation-toggle"><span><strong>Free Trade</strong><small>Does not count against any participating team’s seasonal limit.</small></span><input type="checkbox" data-free-trade-designation="${escapeHtml(String(t.id))}" data-free-trade-kind="${type}" ${t.freeTrade?'checked':''}></label>`
}
function toggleFreeTradeDesignation(kind,idValue,enabled){
 const t=kind==='multi'?multiTrades().find(x=>String(x.id).toLowerCase()===String(idValue).toLowerCase()):trade(idValue),a=me();
 if(!t||!['committee','approved'].includes(t.status)||!canToggleFreeTrade(t,kind,a)){showToast('Free Trade unavailable','You are not eligible to change this trade designation.');return}
 if(!enabled&&t.status==='approved'){
  const prior=t.freeTrade;t.freeTrade=false;const blocked=tradeLimitReviewRows(t,kind).filter(r=>!r.allowed);t.freeTrade=prior;
  if(blocked.length&&a.role!=='commissioner'){showToast('Commissioner required','Changing this approved trade to Standard would place a team over its limit.');return}
  if(blocked.length&&!window.confirm(`Changing this trade to Standard would place ${blocked.map(r=>r.team?.fullName||r.teamId).join(', ')} over the seasonal trade limit. Continue?`))return;
 }
 t.freeTrade=Boolean(enabled);t.updatedAt=now();
 const message=t.freeTrade?`${a.handle} marked the transaction as a Free Trade.`:`${a.handle} changed the transaction to a Standard Trade.`;
 if(kind==='multi'){t.chat=Array.isArray(t.chat)?t.chat:[];t.chat.push({id:id('multi-chat'),authorId:'system',text:message,at:now()});notifyTeams(t.teamIds,t.id,t.freeTrade?'Trade marked Free':'Trade marked Standard',message,t.freeTrade?'free-trade':'standard-trade')}
 else{activity(t,'free-trade-designation',message,a.id);participants(t).forEach(pid=>notify(pid,t.negotiationId||t.id,t.freeTrade?'Trade marked Free':'Trade marked Standard',message,t.freeTrade?'free-trade':'standard-trade'))}
 save();showToast(t.freeTrade?'Free Trade enabled':'Standard Trade enabled',t.freeTrade?'This transaction will use 0 seasonal trades.':'Normal seasonal trade usage applies.');
 kind==='multi'?renderMultiTradeDetail(t.id):renderDetail(t.negotiationId||t.id)
}
function legacyTradeUnits(t,teamId){const v=ver(t);if(!v)return 0;if(tradeFreeStatus(t,'two').eligible)return 0;const assets=teamId===t.teamAId?v.assetsA:teamId===t.teamBId?v.assetsB:[];return assetUnitCost(assets).units}
