function approvedTradeRecords(teamId){const rows=[];negotiations().forEach(t=>{if(t.status!=='approved'||![t.teamAId,t.teamBId].includes(teamId))return;rows.push({id:String(t.negotiationId||t.id),type:'two',at:t.publicAt||t.updatedAt||t.createdAt||'',units:legacyTradeUnits(t,teamId),freeTrade:tradeFreeStatus(t,'two').eligible,teams:[t.teamAId,t.teamBId]})});multiTrades().forEach(t=>{if(t.status!=='approved'||!(t.teamIds||[]).includes(teamId))return;rows.push({id:String(t.id),type:'multi',at:t.publicAt||t.updatedAt||t.createdAt||'',units:multiTradeUnits(t,teamId),freeTrade:tradeFreeStatus(t,'multi').eligible,teams:[...(t.teamIds||[])]})});return rows.sort((a,b)=>String(b.at).localeCompare(String(a.at)))}
function approvalLimitRowsForLegacy(t){return tradeLimitReviewRows(t,'two')}
function approvalLimitRowsForMulti(t){return tradeLimitReviewRows(t,'multi')}
function multiApprovalLimitCheck(t){const rules=tradeRules();if(!rules.limitEnabled)return{ok:true,rows:[],message:''};const rows=approvalLimitRowsForMulti(t),blocked=rows.filter(row=>!row.allowed);return{ok:blocked.length===0,rows,message:approvalLimitMessage(rows)}}
function approvalLimitMessage(rows){return (rows||[]).filter(r=>!r.allowed).map(r=>`${r.team.fullName} is out of trades. If Trade is Free, please toggle ON.`).join(' ')}
function builderTradeLimitRows(){const b=ensureUnifiedBuilder(),rules=tradeRules();return b.teamIds.map(teamId=>{const assets=b.assetsByTeam[teamId]||[],cost=assetUnitCost(assets),used=committedTradeUnits(teamId,{excludeId:b.tradeId||b.multiTradeId}),remaining=rules.limitEnabled?Math.max(0,Number(rules.seasonTradeLimit)-used):Infinity,units=cost.units,requiresFree=rules.limitEnabled&&units>remaining,allowed=!rules.limitEnabled||units<=remaining||freeTradeDesignationEnabled();return{teamId,team:teamById(teamId),...cost,units,used,remaining,allowed,requiresFree,freeTrade:false}})}
function builderTradeLimitsValid(){return builderTradeLimitRows().every(row=>row.allowed)}
function tradeLimitMessage(){const rules=tradeRules(),bad=builderTradeLimitRows().filter(row=>!row.allowed);if(!rules.limitEnabled||!bad.length)return'';return bad.map(row=>`${row.team.abbr} needs ${row.units} trade${row.units===1?'':'s'} but has ${row.remaining} remaining.`).join(' ')}
function pct(v,fallback=100){const n=Number(v);return Number.isFinite(n)?n/fallback:1}
function setDeepValue(target,path,value){const parts=String(path).split('.');let ref=target;parts.slice(0,-1).forEach(key=>{ref[key]=ref[key]&&typeof ref[key]==='object'?ref[key]:{};ref=ref[key]});ref[parts.at(-1)]=value}
function commissionerControlsTab(){return dataStore?.getString?.('fgc-commissioner-controls-tab','trade-value')||'trade-value'}
function setCommissionerControlsTab(tab){dataStore?.setString?.('fgc-commissioner-controls-tab',tab,{source:'commissioner-controls-navigation'})}
function projectionCategoryFromSlot(slot){const n=Math.max(1,Math.min(32,Number(slot)||16));return n<=10?'early':n<=20?'mid':n<=28?'late':'super-bowl'}function projectionCategorySlot(category){return category==='early'?5.5:category==='mid'?15.5:category==='late'?24.5:30.5}function projectionCategoryLabel(category){return category==='early'?'Early (Picks 1–10)':category==='mid'?'Mid (Picks 11–20)':category==='late'?'Late (Picks 21–28)':'Super Bowl (Picks 29–32)'}function projectionSlot(teamId){const ps=store?.pickSettings||defaultPickSettings();if((ps.leagueSeason||1)<=3){const raw=ps.manualSlots?.[teamId]??16;const category=typeof raw==='string'?raw:projectionCategoryFromSlot(raw);return projectionCategorySlot(category)}const hist=ps.history?.[teamId]||[];if(hist.length)return Math.max(1,Math.min(32,Math.round(hist.reduce((a,b)=>a+Number(b||0),0)/hist.length)));const raw=ps.manualSlots?.[teamId]??16;return projectionCategorySlot(typeof raw==='string'?raw:projectionCategoryFromSlot(raw))}
function projectionMultiplier(slot){const d=tradeValueSettings().draft,early=Number(d.earlyPickMultiplier||134)/100,late=Number(d.latePickMultiplier||84)/100;return early-((Math.max(1,Math.min(32,slot))-1)/31)*(early-late)}
function projectionMode(){return(store?.pickSettings?.leagueSeason||1)<=3?'Manual commissioner/committee projection':'Automatic historical projection'};
