function overallBase(ovr){const m=tradeValueSettings().model,x=Math.max(0,ovr-60);return Math.round(x*x*Number(m.overallQuadratic||4.25)+Math.max(0,ovr-84)*Number(m.overall84Bonus||210)+Math.max(0,ovr-92)*Number(m.overall92Bonus||420))}
