function modelAgeAdjustment(age){const m=tradeValueSettings().model;return Number(age<=23?m.age21_23:age<=26?m.age24_26:age<=29?m.age27_29:age<=32?m.age30_32:m.age33Plus||0)/100}
function positionModelKey(position){const p=String(position||'').toUpperCase();if(['LT','RT','OT'].includes(p))return'OT';if(['LG','RG','OG'].includes(p))return'OG';if(['LE','RE','EDGE'].includes(p))return'EDGE';if(['LOLB','ROLB','OLB'].includes(p))return'OLB';if(['MLB','ILB'].includes(p))return'MLB';if(['FS','SS','S'].includes(p))return'S';if(['HB','RB'].includes(p))return'RB';if(['K'].includes(p))return'K';if(['P'].includes(p))return'P';if(['FB'].includes(p))return'FB';return p||'C'}
function modelPositionMultiplier(position){const m=tradeValueSettings().model,key=positionModelKey(position);const fallback={QB:134,WR:107,EDGE:120,CB:115,OT:112,DT:109,RB:94,TE:92,OG:102,C:102,MLB:104,OLB:104,S:100,K:45,P:45,FB:72}[key]||100;return Number(m[`position${key}`]??fallback)/100}
function playerValuation(p){if(!p)return{total:0,breakdown:[]};if(!tradeCalculatorEnabled())return{model:MODEL_VERSION,total:0,tradeable:p.injury==='Healthy',enabled:false,breakdown:[]};const settings=tradeValueSettings(),w=settings.player,m=settings.model,rawBase=overallBase(p.overall),base=Math.round(rawBase*pct(w.overall)),age=Math.round(rawBase*((ageFactor(p)+modelAgeAdjustment(p.age))-1)*pct(w.age)),devRate=({'Normal':0,'Star':Number(m.devStar||8)/100,'Superstar':Number(m.devSuperstar||18)/100,'X-Factor':Number(m.devXFactor||28)/100}[p.dev]||0)*(p.age<=24?1.16:p.age>=31?.76:1),dev=Math.round(rawBase*devRate*pct(w.development)),positionKey=positionModelKey(p.position),pos=Math.round(rawBase*(modelPositionMultiplier(p.position)-1)*pct(w.position)),market=Math.max(1,(p.overall-68)*.62),capEfficiency=(market-(p.capHit||0))/Math.max(5,market),capRate=Number(m.contractCapEfficiencyRate??15)/100,maxPremium=Number(m.contractMaxPremium??20)/100,maxPenalty=Number(m.contractMaxPenalty??24)/100,rookie=(p.age<=24&&p.years>=3)?Math.round(rawBase*(Number(m.contractRookiePremium??13)/100)):0,yearsControl=p.years>=4?Math.round(rawBase*(Number(m.contractFourYearControl??6)/100)):p.years===1?-Math.round(rawBase*(Number(m.contractExpiringPenalty??7)/100)):0,contract=Math.round((Math.round(rawBase*Math.max(-maxPenalty,Math.min(maxPremium,capEfficiency*capRate)))+rookie+yearsControl)*pct(w.contract)),production=Math.round(productionScore(p)*pct(w.production)),elite=Math.round((p.overall>=95?rawBase*.13:p.overall>=90?rawBase*.06:0)*pct(w.elite)),risk=Math.round((p.injury!=='Healthy'?-rawBase*.35:0)*pct(w.injury)),total=Math.max(100,base+age+dev+pos+contract+production+elite+risk);return{model:MODEL_VERSION,total,tradeable:p.injury==='Healthy',breakdown:[['Overall rating',base,`${p.overall} OVR curved base · ${w.overall}% weight`],['Age & window',age,`${p.age} years · ${w.age}% weight`],['Development',dev,`${p.dev} · ${w.development}% weight`],['Contract & control',contract,`${p.years} yrs · ${formatMoney(p.capHit)} cap hit · ${w.contract}% weight`],['Production',production,`${w.production}% weight`],['Position scarcity',pos,`${positionKey} · ${w.position}% weight`],['Elite premium',elite,p.overall>=90?`${w.elite}% weight`:'Not applied'],['Risk',risk,`${p.injury} · ${w.injury}% weight`]]}}
function leagueYear(){return Number(store?.pickSettings?.timeline?.leagueYear||2026)}
function draftDistance(year){return Math.max(1,Number(year)-leagueYear())}
function retainedValue(distance){const values=tradeValueSettings().draft.futureRetention||{};const pctValue=Number(values[distance]);if(Number.isFinite(pctValue))return pctValue/100;const third=Number(values[3]||40)/100;return Math.max(.18,third-Math.max(0,distance-3)*.08)}
function pickValuation(a){if(!tradeCalculatorEnabled())return{model:PICK_VERSION,total:0,slot:projectionSlot(a.teamId),mode:projectionMode(),distance:draftDistance(a.year),discount:0,enabled:false,breakdown:[]};const baseByRound=tradeValueSettings().draft.roundBases||{};const base=Number(baseByRound[a.round]||100),slot=projectionSlot(a.teamId),projectionMult=projectionMultiplier(slot),distance=draftDistance(a.year),discount=retainedValue(distance),projected=Math.round(base*(projectionMult-1)),future=Math.round(base*projectionMult*(discount-1)),total=Math.max(50,Math.round(base*projectionMult*discount));return{model:PICK_VERSION,total,slot,mode:projectionMode(),distance,discount,breakdown:[['Round base',base,`${a.year} Round ${a.round}`],['Internal projection adjustment',projected,'Projected Draft Slot Value'],['Timeline adjustment',future,`${distance===1?'Next draft':distance===2?'Two drafts away':`${distance} drafts away`} · ${(discount*100).toFixed(0)}% retained value`]]}}
