 if(list.length>=3){let amount=0;list.slice(2).forEach((item,index)=>{const rate=index===0?.08:.14;amount-=Math.round(item.value*rate*pct(pw.dilution))});adjustment+=amount;rows.push(['Package dilution',amount,`${list.length} assets · lower-value pieces discounted`]);}
 const playerCount=list.filter(x=>x.player).length;if(playerCount>2){const amount=Math.round(-(playerCount-2)*125*pct(pw.rosterSpot));adjustment+=amount;rows.push(['Roster-spot cost',amount,`${playerCount} players require extra roster space`]);}
