function total(a,b=[]){return packageValuation(a,b).total}
function fair(a,b){return a&&b?Math.round(Math.min(a,b)/Math.max(a,b)*1000)/10:0}
function calcVisible(t,a=me()){if(!tradeCalculatorEnabled())return false;if(!t)return true;if(t.status==='approved')return false;if(involved(t,a))return true;if(['committee','committee-rejected','rejected'].includes(t.status)&&['committee','commissioner'].includes(a.role))return true;return false}
function breakdownRows(p){const v=playerValuation(p);return v.breakdown.map(([label,val,note])=>`<div class="value-breakdown-row"><span><strong>${escapeHtml(label)}</strong><small>${escapeHtml(note)}</small></span><b class="${val<0?'is-negative':''}">${val>=0?'+':''}${val.toLocaleString()}</b></div>`).join('')}
function packageRows(pkg,label){return`<div class="package-engine-side"><div class="package-engine-side__header"><strong>${label}</strong><span>${pkg.raw.toLocaleString()} raw → ${pkg.total.toLocaleString()} adjusted</span></div>${pkg.rows.length?pkg.rows.map(([name,val,note])=>`<div class="package-engine-row"><span><b>${escapeHtml(name)}</b><small>${escapeHtml(note)}</small></span><strong class="${val<0?'is-negative':'is-positive'}">${val>=0?'+':''}${val.toLocaleString()}</strong></div>`).join(''):'<div class="package-engine-empty">No package-level adjustment.</div>'}</div>`}
function calculationPanel(t,v,title='Fair Trade Calculator'){if(!tradeCalculatorEnabled())return'';const pa=packageValuation(v.assetsA,v.assetsB),pb=packageValuation(v.assetsB,v.assetsA),va=pa.total,vb=pb.total,f=fair(va,vb),A=teamById(t.teamAId),B=teamById(t.teamBId);return`<article class="private-calculation valuation-panel card"><div class="private-calculation__header"><div><h3>${title}</h3></div><span class="pill ${f>=91?'pill--success':f>=85?'pill--warning':'pill--danger'}">${f}% fair</span></div><div class="calculation-comparison"><div><span>${A.abbr} sends</span><strong>${va.toLocaleString()}</strong><small>${pa.adjustment>=0?'+':''}${pa.adjustment.toLocaleString()} package adj.</small></div><div class="fairness-meter"><span style="width:${f}%"></span></div><div><span>${B.abbr} sends</span><strong>${vb.toLocaleString()}</strong><small>${pb.adjustment>=0?'+':''}${pb.adjustment.toLocaleString()} package adj.</small></div></div><details class="package-engine-details"><summary><span><svg><use href="#icon-info"></use></svg>View package-engine adjustments</span><strong>${PACKAGE_VERSION}</strong></summary><div class="package-engine-grid">${packageRows(pa,A.abbr)}${packageRows(pb,B.abbr)}</div></details><p><svg><use href="#icon-info"></use></svg>Click a player in the trade package above to open the complete player card and individual valuation. The fairness bar itself is not interactive.</p></article>`}
function renderAsset(a,opt={}){if(a.type==='player'){const p=playerById(a.id),t=teamById(p.teamId);return`<button type="button" class="trade-asset trade-asset--player" data-open-value-card="${p.id}"><span class="player-avatar" style="${teamStyle(t)}">${p.initials}</span><span class="trade-asset__copy"><strong>${escapeHtml(p.name)}</strong><small>${p.position} · ${p.overall} OVR · ${p.age} yrs · ${p.dev}</small></span>${opt.isNew?'<span class="asset-new-tag">NEW</span>':''}${opt.val&&tradeCalculatorEnabled()?`<span class="asset-value">${value(a).toLocaleString()}</span>`:''}${opt.remove?`<span class="icon-button icon-button--small" data-remove-asset="${assetKey(a)}" data-side="${opt.side}"><svg><use href="#icon-close"></use></svg></span>`:''}</button>`}return`<button type="button" class="trade-asset trade-asset--pick" data-open-pick-card="${a.teamId}:${a.year}:${a.round}"><span class="pick-mark">R${a.round}</span><span class="trade-asset__copy"><strong>${a.year} Round ${a.round} Pick</strong><small>${teamById(a.teamId).fullName}</small></span>${opt.isNew?'<span class="asset-new-tag">NEW</span>':''}${opt.val&&tradeCalculatorEnabled()?`<span class="asset-value">${value(a).toLocaleString()}</span>`:''}${opt.remove?`<span class="icon-button icon-button--small" data-remove-asset="${assetKey(a)}" data-side="${opt.side}"><svg><use href="#icon-close"></use></svg></span>`:''}</button>`}

function avg(...values){const nums=values.filter(Number.isFinite);return nums.length?Math.round(nums.reduce((a,b)=>a+b,0)/nums.length):0}
function inferredRating(p,key,offset=0){const known=p.ratings?.[key];if(Number.isFinite(known))return known;let h=0;for(const c of `${p.id}-${key}`)h=(h*31+c.charCodeAt(0))%997;return Math.max(45,Math.min(99,p.overall+offset+(h%13)-6))}
function keyAttributes(p){const r=p.ratings||{},pos=p.position;
 const speed=inferredRating(p,'Speed'),agility=inferredRating(p,'Agility'),aware=inferredRating(p,'Awareness');
 if(pos==='QB')return[['Speed',speed],['Agility',agility],['Awareness',aware],['Throw Power',inferredRating(p,'Throw Power',2)],['Accuracy',avg(inferredRating(p,'Short Accuracy',1),inferredRating(p,'Medium Accuracy'),inferredRating(p,'Deep Accuracy',-2))]];
 if(['WR','TE'].includes(pos))return[['Speed',speed],['Route Running',avg(inferredRating(p,'Short Route'),inferredRating(p,'Medium Route'),inferredRating(p,'Deep Route',-1))],['Catching',avg(inferredRating(p,'Catching'),inferredRating(p,'Catch in Traffic'),inferredRating(p,'Spectacular Catch'))],['Agility',agility],['Release',inferredRating(p,'Release')]];
 if(['RB','FB'].includes(pos))return[['Speed',speed],['Acceleration',inferredRating(p,'Acceleration')],['Agility',agility],['Carrying',inferredRating(p,'Carrying')],['Elusiveness',avg(inferredRating(p,'Juke Move'),inferredRating(p,'Spin Move'),inferredRating(p,'Change of Direction'))]];
 if(['LT','LG','C','RG','RT'].includes(pos))return[['Strength',inferredRating(p,'Strength')],['Awareness',aware],['Pass Blocking',avg(inferredRating(p,'Pass Block'),inferredRating(p,'Pass Block Power'),inferredRating(p,'Pass Block Finesse'))],['Run Blocking',avg(inferredRating(p,'Run Block'),inferredRating(p,'Run Block Power'),inferredRating(p,'Run Block Finesse'))],['Impact Blocking',inferredRating(p,'Impact Blocking')]];
 if(['CB','FS','SS'].includes(pos))return[['Speed',speed],['Agility',agility],['Man Coverage',inferredRating(p,'Man Coverage')],['Zone Coverage',inferredRating(p,'Zone Coverage')],['Play Recognition',inferredRating(p,'Play Recognition')]];
 if(['LE','RE','DT','LOLB','MLB','ROLB'].includes(pos))return[['Speed',speed],['Strength',inferredRating(p,'Strength')],['Tackling',inferredRating(p,'Tackling')],['Block Shedding',inferredRating(p,'Block Shedding')],['Pass Rush',avg(inferredRating(p,'Power Moves'),inferredRating(p,'Finesse Moves'))]];
 return[['Kick Power',inferredRating(p,'KickPower')],['Accuracy',inferredRating(p,'Accuracy')],['Awareness',aware],['Speed',speed],['Agility',agility]]}
function seasonStats(p){
 const current=p.stats||{},years=[2026,2025,2024];
 return years.map((year,i)=>{
  const factor=i===0?1:i===1?.91:.84,scale=v=>Math.round((Number(v)||0)*factor),full=i?2:1;
  if(p.position==='QB')return{year,items:[['GP',i?17:current.games],['PASS YDS',scale(current.passingYards)*full],['PASS TD',scale(current.passingTD)*full],['INT',Math.max(1,scale(current.interceptions)*full)],['CMP%',`${Math.max(52,(current.compPct||62)-i*1.3).toFixed(1)}%`]]};
  if(['RB','FB'].includes(p.position))return{year,items:[['GP',i?17:current.games],['RUSH YDS',scale(current.rushingYards)*full],['RUSH TD',scale(current.rushingTD)*full],['REC',scale(current.receptions)*full],['REC YDS',scale(current.receivingYards)*full]]};
  if(['WR','TE'].includes(p.position))return{year,items:[['GP',i?17:current.games],['REC',scale(current.receptions)*full],['REC YDS',scale(current.receivingYards)*full],['REC TD',scale(current.receivingTD)*full],['YPC',(Number(current.yardsPerCatch||12)-i*.4).toFixed(1)]]};
  if(['K','P'].includes(p.position))return{year,items:Object.entries(current).filter(([k])=>!['games','fantasy'].includes(k)).slice(0,4).map(([k,v])=>[k.toUpperCase(),typeof v==='number'?scale(v):v])};
  return{year,items:[['GP',i?17:current.games],['TACKLES',scale(current.tackles)*full],['SACKS',(Number(current.sacks||0)*factor*full).toFixed(1)],['INT',scale(current.interceptions)*full],['FF',scale(current.forcedFumbles)*full]]};
 });
}
