function renderNotificationMenu(){if(window.FranchiseHQ?.liveTradeCenter?.renderNotificationMenu?.())return;const a=me(),items=(store.notifications||[]).filter(n=>n.accountId===a.id),panel=document.querySelector('[data-notification-menu]'),dot=document.querySelector('.notification-dot');if(dot)dot.hidden=!unreadCount(a);if(!panel)return;panel.innerHTML=`<div class="notification-menu__header"><div><span class="eyebrow">Notifications</span><strong>Recent trade activity</strong></div><div class="notification-menu__header-actions"><span class="pill ${unreadCount(a)?'pill--warning':'pill--neutral'}">${unreadCount(a)} unread</span>${unreadCount(a)?'<button type="button" class="text-button" data-mark-all-notifications-read>Mark all read</button>':''}</div></div><div class="notification-menu__list">${items.length?items.slice(0,20).map(n=>`<button data-notification-id="${escapeHtml(String(n.id))}" data-notification-trade="${escapeHtml(String(n.tradeId))}" class="${n.read?'':'is-unread'}"><span><strong>${escapeHtml(n.title)}</strong><small>${escapeHtml(n.text)}</small></span><em>${escapeHtml(n.at)}</em></button>`).join(''):'<div class="notification-menu__empty"><strong>You are all caught up</strong><small>Trade offers, counters, reviews, and decisions will appear here.</small></div>'}</div>`}
function ownerDecisionBadges(t){
 const v=ver(t),a=me(),target=v?.targetId===a.id,proposer=v?.proposerId===a.id;
 if(t.status==='negotiating')return `<div class="trade-decision-strip"><span class="decision-chip ${proposer?'is-current':'is-muted'}">${proposer?'Offer sent':'Participant'}</span><span class="decision-chip ${target?'is-pending':'is-muted'}">${target?'Your decision required':`Waiting on ${escapeHtml(acc(v?.targetId)?.handle||'owner')}`}</span></div>`;
 if(t.status==='committee'){const mine=t.votes?.[a.id],recused=committeeConflict(t,a);return `<div class="trade-decision-strip"><span class="decision-chip is-accepted">Owners accepted</span>${canReviewTrades(a)?`<span class="decision-chip ${recused?'is-muted':mine?'is-voted':'is-pending'}">${recused?'Awaiting committee review · You are recused':mine?`You voted ${escapeHtml(mine.vote)}`:'Your committee review is pending'}</span>`:''}</div>`}
 if(t.status==='approved')return `<div class="trade-decision-strip"><span class="decision-chip is-approved">Committee approved</span></div>`;
 if(['rejected','committee-rejected'].includes(t.status)){const who=t.rejectionSource==='committee'||t.status==='committee-rejected'?'Rejected by Trade Committee':`Rejected by ${escapeHtml(t.rejectedByName||acc(t.rejectedBy)?.handle||'Participant')}`;return `<div class="trade-decision-strip"><span class="decision-chip is-rejected">${who}</span></div>`;}
 return '';
}
