function committeeBucketTwo(t,a=me()){if(involved(t,a))return'participating';if(canReviewTrades(a)&&!committeeConflict(t,a)&&t.votes?.[a.id])return'addressed';if(canReviewTrades(a)&&!committeeConflict(t,a)&&!t.votes?.[a.id])return'needs-action';return'none'}
function filtered(){autoCancelInvalidCommitteeTrades();let a=negotiations().filter(visible).sort((x,y)=>Number(y.id)-Number(x.id)),meNow=me();if(ui.tab==='drafts')return a.filter(t=>t.status==='draft'&&t.creatorId===meNow.id);if(ui.tab==='sent')return a.filter(t=>t.status==='negotiating'&&sameParty(meNow,ver(t).proposerId));if(ui.tab==='received')return a.filter(t=>t.status==='negotiating'&&sameParty(meNow,ver(t).targetId));if(ui.tab==='committee')return a.filter(t=>t.status==='committee'&&committeeBucketTwo(t,meNow)===ui.committeeFilter);if(ui.tab==='approved')return a.filter(t=>t.status==='approved'&&involved(t,meNow));if(ui.tab==='rejected')return a.filter(t=>['rejected','committee-rejected','cancelled'].includes(t.status)&&involved(t,meNow));if(ui.tab==='history')return a.filter(t=>t.status==='approved');return []}
function historyVisible(t){return t.status==='approved'}
function historyDecisionLabel(t){if(t.status==='approved')return'Approved';if(t.status==='rejected')return'Not approved';if(t.status==='withdrawn')return'Withdrawn';if(t.status==='declined')return'Declined';return'Expired'}
