function tradeAssetText(asset){
 if(!asset)return'';
 if(asset.type==='player'){const p=playerById(asset.id);return p?`${p.name} ${p.position} ${p.overall} OVR ${p.dev}`:`Player ${asset.id}`}
 const t=teamById(asset.teamId);return `${asset.year} Round ${asset.round} Pick ${t?.abbr||asset.teamId||''}`;
}
function normalizedTradeRecord(kind,row){
 const multi=kind==='multi';
 const teamIds=multi?[...(row.teamIds||[])]:[row.teamAId,row.teamBId].filter(Boolean);
 const assets=multi?(row.transfers||[]).map(x=>x.asset):(()=>{const v=ver(row);return [...(v?.assetsA||[]),...(v?.assetsB||[])]})();
 const status=String(row.status||'').toLowerCase();
 const dateText=row.publicAt||row.updatedAt||row.createdAt||'';
 const parsed=Date.parse(dateText);
 const season=(new Date(Number.isFinite(parsed)?parsed:Date.now())).getFullYear();
 const search=[row.id,row.negotiationId,status,row.rejectedByName,row.cancelReason,...teamIds.flatMap(id=>{const t=teamById(id);return[id,t?.abbr,t?.fullName,t?.owner]}),...assets.map(tradeAssetText)].filter(Boolean).join(' ').toLowerCase();
 return{kind,row,id:String(row.id),teamIds,assets,status,dateText,stamp:Number.isFinite(parsed)?parsed:0,season,search,teamCount:teamIds.length};
}
function allTradeRecords(){return [...negotiations().map(row=>normalizedTradeRecord('two',row)),...multiTrades().map(row=>normalizedTradeRecord('multi',row))]}
function tradeRecordAuthorized(record){return record.status==='approved'}
function tradeRecordMatches(record){
 const q=String(ui.historySearch||'').trim().toLowerCase();if(q&&!record.search.includes(q))return false;
 if(record.status!=='approved')return false;
 if(ui.historyTeam!=='all'&&!record.teamIds.includes(ui.historyTeam))return false;
 if(ui.historyAssetType!=='all'&&!record.assets.some(a=>a.type===ui.historyAssetType))return false;
 if(ui.historyTradeType!=='all'&&String(record.teamCount)!==ui.historyTradeType)return false;
 if(ui.historySeason!=='all'&&String(record.season)!==String(ui.historySeason))return false;
 return true;
}
