 const rows=allTradeRecords().filter(r=>r.assets.some(a=>a.type==='player'&&String(a.id)===String(playerId))).sort((a,b)=>b.stamp-a.stamp).map(r=>{
  let movement='Included in trade';
  if(r.kind==='multi'){const transfer=(r.row.transfers||[]).find(x=>x.asset?.type==='player'&&String(x.asset.id)===String(playerId));if(transfer)movement=`${teamById(transfer.fromTeamId)?.abbr||transfer.fromTeamId} → ${teamById(transfer.toTeamId)?.abbr||transfer.toTeamId}`}
  else{const v=ver(r.row),fromA=(v?.assetsA||[]).some(a=>a.type==='player'&&String(a.id)===String(playerId));movement=fromA?`${teamById(r.row.teamAId)?.abbr} → ${teamById(r.row.teamBId)?.abbr}`:`${teamById(r.row.teamBId)?.abbr} → ${teamById(r.row.teamAId)?.abbr}`}
  return Object.freeze({tradeId:r.id,kind:r.kind,status:r.status,date:r.dateText,movement,confirmed:false,cancelReason:r.row.cancelReason||''});
 });
