function renderConfidencePoolCommissionerCard(){
 try{
  const service=window.FranchiseHQ?.modules?.league?.games;
  if(!service?.confidence)return `<section class="card"><div class="card-header"><div><span class="eyebrow">Confidence Pool</span><h3>Season Entry Control</h3></div><span class="pill pill--warning">Unavailable</span></div><p>The Games service is still initializing. Commissioner navigation remains available.</p></section>`;
  const config=service.confidence.config?.()||{};
  const entries=Object.keys(config.entries||{}).length;
  const schedule=Array.isArray(window.FGC_APP?.schedule)?window.FGC_APP.schedule:[];
  const weekNumbers=schedule.map(item=>Number(item?.week)).filter(Number.isFinite);
  const availableWeeks=weekNumbers.length?weekNumbers:Array.from({length:18},(_,index)=>index+1);
  const openWeeks=Array.isArray(config.openWeeks)?config.openWeeks.map(Number).filter(Number.isFinite):[];
  const firstOpen=openWeeks.length?openWeeks[0]:null;
  const lastOpen=openWeeks.length?openWeeks[openWeeks.length-1]:null;
  const finalWeek=availableWeeks[availableWeeks.length-1]||18;
  const status=String(config.status||'locked').toLowerCase();
  const statusLabel=typeof titleCase==='function'?titleCase(status):status.charAt(0).toUpperCase()+status.slice(1);
  return `<section class="card confidence-commissioner-card"><div class="card-header"><div><span class="eyebrow">Season ${escapeHtml(config.season||'2026')}</span><h3>Confidence Pool Management</h3><p>Open only the weeks owners are currently allowed to complete, then close the pool whenever competitive balance requires it.</p></div><span class="pill ${status==='open'?'pill--success':status==='locked'?'pill--warning':'pill--neutral'}">${escapeHtml(statusLabel)}</span></div><div class="commissioner-status-grid">${commissionerStatusRow('Entry window',status==='open'&&firstOpen!==null?`Weeks ${firstOpen}–${lastOpen} open`:'Restricted',status==='open'?'success':'warning')}${commissionerStatusRow('Saved entries',String(entries),'accent')}${commissionerStatusRow('Scoring','Automatic from final games','neutral')}</div><div class="confidence-window-controls"><label class="field"><span>First open week</span><select data-confidence-window-start>${availableWeeks.map(week=>`<option value="${week}" ${week===(firstOpen||availableWeeks[0])?'selected':''}>${week}</option>`).join('')}</select></label><label class="field"><span>Last open week</span><select data-confidence-window-end>${availableWeeks.map(week=>`<option value="${week}" ${week===(lastOpen||finalWeek)?'selected':''}>${week}</option>`).join('')}</select></label></div><div class="heading-actions" style="justify-content:flex-start"><button class="button button--primary" data-confidence-open-window>Open Selected Weeks</button><button class="button button--ghost" data-confidence-pool-status="locked" ${status==='locked'?'disabled':''}>Close Confidence Pool</button><button class="button button--ghost" data-route="schedule">View Confidence Pool</button></div></section>`;
 }catch(error){
  console.error('Confidence Pool Commissioner card failed to render.',error);
  return `<section class="card confidence-commissioner-card"><div class="card-header"><div><span class="eyebrow">Confidence Pool</span><h3>Management temporarily unavailable</h3></div><span class="pill pill--warning">Action Required</span></div><p>The Confidence Pool control could not load, but Commissioner HQ navigation and the remaining tools are still available.</p></section>`;
 }
}
