 try{const response=await fetch(`/api/leagues/${encodeURIComponent(slug)}/memberships`,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({userId,role,teamId,reactivate})});const data=await response.json();if(!response.ok)throw new Error(data?.error||`Request failed (${response.status})`);showToast(reactivate?'Member reactivated':'Membership updated',reactivate?'Platform access, team, and league role are active again.':'Discord access, team, and league role are now active.');await loadCommissionerMembers();await refreshCanonicalOwnership();renderCommissioner('teams');return true}catch(error){showToast('Membership not updated',error.message||String(error));return false}
