function renderCurrentDataSourceCard(state){const snap=currentDataSnapshot();const games=snapshotRows(snap,'games','schedule','schedules');const transactions=snapshotRows(snap,'transactions','playerTransactions','transactionHistory');const counts=state?.counts||{};const teams=snapshotRows(snap,'teams');const players=snapshotRows(snap,'players');const weeks=games.map(g=>Number(g.week??g.weekIndex??g.scheduleWeek??g.weekNumber)).filter(Number.isFinite);const unfinished=games.filter(g=>!/final|complete|played/i.test(String(g.status||g.gameStatus||g.state||''))).map(g=>Number(g.week??g.weekIndex??g.scheduleWeek??g.weekNumber)).filter(Number.isFinite);const currentWeek=Number(snap?.league?.currentWeek||snap?.season?.currentWeek||snap?.currentWeek||window.FranchiseHQ?.modules?.league?.games?.getCurrentWeek?.()||0)||(unfinished.length?Math.min(...unfinished):(weeks.length?Math.max(...weeks):0))||'—';const view=leagueDataModePresentation(state);return `<article class="card league-source-card commissioner-current-source"><div class="card-header"><div><span class="eyebrow">Current Data Source</span><h3>${view.label}</h3><p>${escapeHtml(view.description)}</p></div><span class="pill pill--${view.tone}">${view.status}</span></div><div class="commissioner-source-metrics"><div><span>Teams</span><strong>${Number(counts.teams||teams.length||0).toLocaleString()}</strong></div><div><span>Players</span><strong>${Number(counts.players||players.length||0).toLocaleString()}</strong></div><div><span>Schedule Games</span><strong>${games.length.toLocaleString()}</strong></div><div><span>Current Week</span><strong>${currentWeek}</strong></div><div><span>Transactions</span><strong>${transactions.length.toLocaleString()}</strong></div><div><span>Last Import</span><strong>${state?.activeMode==='live'?leagueDataDate(state?.importedAt):state?.activeMode==='demo'?'Development Data':'Not applicable'}</strong></div></div></article>`}
