  const [snapshot,teamRows,standingRows,gameRows]=await Promise.all([live.getSnapshot?.(),live.getTeams?.()||[],live.getStandings?.()||[],live.getSchedule()]);
  const games=Array.isArray(gameRows)?gameRows:[];
