  const currentWeek=Number(snapshot?.weekIndex??snapshot?.currentWeek??snapshot?.week??window.FranchiseHQ?.currentSeasonContext?.week??games.find(g=>!/final|complete/i.test(String(g.status||g.gameStatus||g.state||'')))?.weekIndex??1)||1;
  commissionerCanonicalSchedule={loading:false,loaded:true,games,teams,context:{week:currentWeek,season:Number(snapshot?.seasonYear??snapshot?.season??2026)||2026},error:null};
  window.FranchiseHQ?.modules?.league?.games?.hydrateCanonicalSchedule?.(games,teams,commissionerCanonicalSchedule.context);
