// v5.7.1a — Trade Block controls & team-needs cleanup
const BLOCK_POSITION_NEEDS=['QB','WR','EDGE','CB','OT','DT','RB','TE','OG','C','MLB','OLB','S','K','P','FB'];
const BLOCK_PICK_NEEDS=['1','2','3','4','5','6','7','future'];
const BLOCK_PICK_LABELS={'1':'1st Round','2':'2nd Round','3':'3rd Round','4':'4th Round','5':'5th Round','6':'6th Round','7':'7th Round',future:'Future Picks'};
function teamBlockNeeds(teamId){store.blockNeeds=store.blockNeeds||{};const current=store.blockNeeds[teamId]||{};current.positions=Array.isArray(current.positions)?current.positions:[];current.picks=Array.isArray(current.picks)?current.picks:[];store.blockNeeds[teamId]=current;return current}
function needPositionGroup(position){const p=String(position||'').toUpperCase();if(['LE','RE','EDGE'].includes(p))return'EDGE';if(['LT','RT','OT'].includes(p))return'OT';if(['LG','RG','OG'].includes(p))return'OG';if(['FS','SS','S'].includes(p))return'S';return p}
function assetNeedKey(asset){if(asset?.type==='player'){const p=playerById(asset.id);return{kind:'position',key:needPositionGroup(p?.position)}}if(asset?.type==='pick')return{kind:'pick',key:String(asset.round),future:Number(asset.year)>leagueYear()+1};return{kind:'unknown',key:''}}
function assetSatisfiesNeeds(asset,needs){const k=assetNeedKey(asset);return k.kind==='position'&&needs.positions.includes(k.key)}
function listedAssetsForTeam(teamId){const result=[];players.filter(p=>p.teamId===teamId&&onBlock(p)).forEach(p=>result.push(P(p)));Object.entries(store.blockPicks||{}).forEach(([key,active])=>{if(!active)return;const [ownerId,year,round]=key.split(':');if(ownerId===teamId)result.push(D(ownerId,Number(year),Number(round)))});return result}
function needsLabel(needs){const values=[...needs.positions];return values.length?values.join(' · '):'No team needs selected'}
function needMatchDetails(ownNeeds,partnerNeeds,assetsA,assetsB){const ownHits=assetsB.filter(a=>assetSatisfiesNeeds(a,ownNeeds));const partnerHits=assetsA.filter(a=>assetSatisfiesNeeds(a,partnerNeeds));const ownDen=Math.max(1,ownNeeds.positions.length),partnerDen=Math.max(1,partnerNeeds.positions.length);const score=Math.round(Math.min(100,((ownHits.length/ownDen)+(partnerHits.length/partnerDen))*50));return{score,ownHits,partnerHits}}
function pickBestListedAsset(assets,needs,desiredValue=0){const matching=assets.filter(a=>assetSatisfiesNeeds(a,needs));if(!matching.length)return null;if(!tradeCalculatorEnabled())return matching[0];return matching.slice().sort((a,b)=>Math.abs(value(a)-desiredValue)-Math.abs(value(b)-desiredValue))[0]}

generateAISuggestions=function(){
 const a=me();if(!a.teamId)return[];const ownId=a.teamId,ownNeeds=teamBlockNeeds(ownId),ownListed=listedAssetsForTeam(ownId);
 if(!ownListed.length||!ownNeeds.positions.length)return[];
 const suggestions=[];
 teams.filter(t=>t.id!==ownId).forEach(partner=>{
  if(tradeRules().limitEnabled&&remainingTradeCredits(partner.id)<=0&&!tradeRules().freeTradeDesignationEnabled)return;
  const partnerNeeds=teamBlockNeeds(partner.id),partnerListed=listedAssetsForTeam(partner.id);
  if(!partnerListed.length||!partnerNeeds.positions.length)return;
  const receive=pickBestListedAsset(partnerListed,ownNeeds,0);if(!receive)return;
  const send=pickBestListedAsset(ownListed,partnerNeeds,tradeCalculatorEnabled()?value(receive):0);if(!send)return;
  const assetsA=[send],assetsB=[receive];
  if(tradeCalculatorEnabled()){
   const sendValue=total(assetsA),receiveValue=total(assetsB);
   if(sendValue<receiveValue*.72){const extra=ownListed.filter(x=>assetKey(x)!==assetKey(send)&&assetSatisfiesNeeds(x,partnerNeeds)).sort((x,y)=>Math.abs((sendValue+value(x))-receiveValue)-Math.abs((sendValue+value(y))-receiveValue))[0];if(extra)assetsA.push(extra)}
   else if(receiveValue<sendValue*.72){const extra=partnerListed.filter(x=>assetKey(x)!==assetKey(receive)&&assetSatisfiesNeeds(x,ownNeeds)).sort((x,y)=>Math.abs((receiveValue+value(x))-sendValue)-Math.abs((receiveValue+value(y))-sendValue))[0];if(extra)assetsB.push(extra)}
  }
  const match=needMatchDetails(ownNeeds,partnerNeeds,assetsA,assetsB),fairness=tradeCalculatorEnabled()?fair(total(assetsA),total(assetsB)):null;
  if(!match.ownHits.length||!match.partnerHits.length)return;
  suggestions.push({id:`block-ai-${ownId}-${partner.id}`,teamAId:ownId,teamBId:partner.id,assetsA,assetsB,target:receive,fairness,needsMatch:Math.max(50,match.score),reason:`${teamById(ownId)?.abbr||ownId} receives ${match.ownHits.map(assetLabel).join(', ')} for a stated need. ${partner.abbr} receives ${match.partnerHits.map(assetLabel).join(', ')} for a stated need.`});
 });
 return suggestions.sort((x,y)=>(y.needsMatch-x.needsMatch)||((y.fairness||0)-(x.fairness||0))).slice(0,8)
};

renderAISuggestions=function(){
 const a=me();let content='';if(!canCreateTrade(a)){content=`<article class="empty-state card"><h2>Team identity required</h2><p>Switch to an owner identity with an assigned franchise.</p></article>`;pageContent.innerHTML=tradeCenterShell(content,'suggestions');return}
 const own=teamById(a.teamId),remaining=remainingTradeCredits(a.teamId);if(tradeRules().limitEnabled&&remaining<=0&&!tradeRules().freeTradeDesignationEnabled){content=`<article class="empty-state card ai-trade-limit-empty"><span class="pill pill--danger">TEAM IS OUT OF TRADES</span><h2>No Suggestions Available</h2><p>${escapeHtml(own.fullName)} cannot build a suggestion until trades are available.</p></article>`;pageContent.innerHTML=tradeCenterShell(content,'suggestions');return}
 try{ui.aiSuggestions=generateAISuggestions()}catch(error){console.error('[Franchise HQ] needs-based AI suggestion generation failed',error);ui.aiSuggestions=[]}
 const ownNeeds=teamBlockNeeds(a.teamId),ownListed=listedAssetsForTeam(a.teamId);
 content=`<div class="section-heading"><div><h2>AI Trade Suggestions</h2><p>Suggestions use only Trade Block assets and mutual team needs.</p></div><div class="heading-actions"><button class="button button--ghost" data-route="trade-block">Manage Trade Block</button><button class="button button--ghost" data-refresh-ai>Refresh suggestions</button></div></div><article class="card ai-market-readiness ai-market-readiness--two"><div><span>Assets listed</span><strong>${ownListed.length}</strong></div><div><span>Team needs</span><strong>${ownNeeds.positions.length}</strong></div></article>${ui.aiSuggestions.length?`<div class="ai-suggestion-grid">${ui.aiSuggestions.map((s,i)=>{const partner=teamById(s.teamBId);return `<article class="ai-suggestion-card card"><div class="ai-suggestion-card__head"><div>${renderTeamMark(partner,'team-logo')}<span><strong>${escapeHtml(partner.fullName)}</strong><small>${escapeHtml(partner.owner||'')}</small></span></div><div class="ai-score-stack"><span class="pill pill--accent">Needs Match ${s.needsMatch}%</span>${tradeCalculatorEnabled()?`<span class="pill ${s.fairness>=90?'pill--success':s.fairness>=80?'pill--warning':'pill--neutral'}">Trade Balance ${s.fairness}%</span>`:''}</div></div><div class="ai-package"><div><small>${own.abbr} sends</small>${s.assetsA.map(suggestionAssetLine).join('')}</div><span class="trade-swap"><svg><use href="#icon-swap"></use></svg></span><div><small>${own.abbr} receives</small>${s.assetsB.map(suggestionAssetLine).join('')}</div></div><div class="ai-rationale"><strong>Needs satisfied</strong><p>${escapeHtml(s.reason)}</p></div><div class="ai-suggestion-card__actions"><button class="button button--primary" data-build-ai="${i}">Build This Trade</button></div></article>`}).join('')}</div>`:`<article class="empty-state card"><h2>No mutual Trade Block matches</h2><p>List at least one asset and select team needs. A partner must also list an asset that fits your needs while needing something you have listed.</p><button class="button button--primary" data-route="trade-block">Manage Trade Block</button></article>`}`;
 pageContent.innerHTML=tradeCenterShell(content,'suggestions')
};

