 const pickListings=Object.keys(store.blockPicks||{}).filter(k=>store.blockPicks[k]).map(k=>{const[teamId,year,round]=k.split(':');return{key:k,asset:D(teamId,Number(year),Number(round)),teamId}}).filter(x=>!ui.blockMine||x.teamId===a.teamId).filter(x=>ui.blockTeam==='All'||x.teamId===ui.blockTeam).filter(x=>ui.blockAssetType==='all'||ui.blockAssetType==='picks').filter(x=>ui.blockRound==='All'||String(x.asset.round)===ui.blockRound).filter(x=>!term||`${x.asset.year} round ${x.asset.round} ${teamById(x.teamId)?.fullName||''}`.toLowerCase().includes(term));
