function getTeamOwnerAssignment(teamId){
 const team=teamById(String(teamId||'').toLowerCase())||commissionerTeamById(teamId);
 if(!team||!team.owner||team.owner==='Unassigned')return null;
 const stableId=String(team.id||teamId||'').toLowerCase();
 return {
   teamId:stableId,
   ownerId:`owner-${stableId}`,
   control:'user',
   role:team.ownerRole||'team_owner',
   tradeCommittee:['commissioner','trade_committee'].includes(team.ownerRole),
   id:`owner-${stableId}`,
   handle:team.owner,
   name:team.owner
 };
}
function getTeamOwnerAssignments(){
 const result={};
 teams.forEach(team=>{const teamId=String(team.id||'').toLowerCase();
   result[teamId]=getTeamOwnerAssignment(teamId);
 });
 return result;
}
